"""Markdown report of the electronics check (strido_verify.electronics): pins, buses, channels, currents."""

from typing import Any

LEG_ORDER = ("FL", "FR", "RL", "RR")


def render_report(model: dict[str, Any], findings: list, currents: dict[str, float]) -> str:
    """docs/verification/electronics.md from the model, the findings and the worst-case branch currents."""
    pads = model["controller"]["pads"]
    lines = [
        "# Electronics check",
        "",
        "Generated by `strido_verify.electronics` from `hardware/electronics.yaml` and the firmware pin header "
        "`firmware/strido_esp32s3/src/board_config.h`. Do not edit by hand.",
        "",
        "## XIAO ESP32-S3 pins",
        "",
        "| Pad | GPIO | Function | Connects to | Firmware constant | Note |",
        "|---|---|---|---|---|---|",
    ]
    for pin in model["controller"]["pins"]:
        lines.append(
            f"| {pin['pad']} | {pads[pin['pad']]} | {pin['function']} | {pin['to']} | `{pin['constant']}` | {pin.get('note', '')} |"
        )
    lines += [
        "",
        "## I²C bus",
        "",
        f"{model['i2c']['frequency_hz'] // 1000} kHz.",
        "",
        "| Address | Device | Note |",
        "|---|---|---|",
    ]
    for device in model["i2c"]["devices"]:
        lines.append(f"| 0x{device['address']:02X} | {device['device']} | {device.get('note', '')} |")
    lines += ["", "## PCA9685 servo channels", "", "| Leg | hip | thigh | calf (knee crank) |", "|---|---|---|---|"]
    for leg in LEG_ORDER:
        channels = model["servos"]["channels"][leg]
        lines.append(f"| {leg} | {channels['hip']} | {channels['thigh']} | {channels['calf']} |")
    lines += ["", "## Worst-case currents", "", "| Branch | Current (A) |", "|---|---|"]
    lines += [f"| {name} | {value:.2f} |" for name, value in currents.items()]
    failed = [f for f in findings if not f.ok]
    lines += [
        "",
        f"## Checks: {len(findings) - len(failed)} passed ({sum(not f.margin for f in findings if f.ok)} without margin), "
        f"{len(failed)} failed",
        "",
        "| Check | Result | Detail |",
        "|---|---|---|",
    ]
    lines += [
        f"| {f.check} | {('pass' if f.margin else 'pass, no margin') if f.ok else '**FAIL**'} | {f.detail} |"
        for f in findings
    ]
    return "\n".join(lines) + "\n"
